args.new_string:
import { cookies, headers } from 'next/headers';

export default async function Home() {
  const cookieStore = await cookies();
  const headersList = await headers();

  // Get theme cookie, default to "light" if not found
  const themeCookie = cookieStore.get('theme');
  const theme = themeCookie?.value || 'light';

  // Get Accept-Language header
  const acceptLanguage = headersList.get('accept-language');
  const preferredLanguage = acceptLanguage?.split(',')[0] || 'Not specified';

  return (
    <main>
      <h1>User Preferences</h1>
      <div>
        <h2>Theme Preference</h2>
        <p>Current theme: <strong>{theme}</strong></p>
        {!themeCookie && <p><em>(Using default theme)</em></p>}
      </div>
      <div>
        <h2>Language Preference</h2>
        <p>Preferred language: <strong>{preferredLanguage}</strong></p>
      </div>
    </main>
  );
}

